SELECT u.id, u.account, u.name, u.employee_no, u.password_hash, u.phone, u.email, u.org_id, u.company_id, u.position, u.status, u.remark, u.last_login_at, u.created_at, u.created_by, u.updated_at, u.updated_by, u.deleted_at FROM sys_user u WHERE 1 = 1 AND /* @dataScope(table=sys_user, alias=u) */ AND u.deleted_at IS NULL
AND u.status = #{status}
AND u.company_id = #{companyId}
AND u.org_id IN (SELECT so.id FROM sys_org so WHERE so.path LIKE #{orgPathPrefix})
AND u.org_id = #{orgId}
AND (u.name LIKE CONCAT('%', #{keyword}, '%') OR u.account LIKE CONCAT('%', #{keyword}, '%') OR u.employee_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.org_id ASC, u.id ASC

SELECT u.id, u.account, u.name, u.employee_no, u.phone, u.email, u.org_id, u.company_id, u.position, u.status, u.remark, u.created_at, u.updated_at, u.deleted_at FROM sys_user u WHERE 1 = 1 AND /* @dataScope(table=sys_user, alias=u) */ AND u.deleted_at IS NULL AND u.status = 'active'
AND u.org_id IN (SELECT so.id FROM sys_org so WHERE so.path LIKE #{orgPathPrefix})
AND u.org_id = #{orgId}
AND (u.name LIKE CONCAT('%', #{keyword}, '%') OR u.account LIKE CONCAT('%', #{keyword}, '%') OR u.employee_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.org_id ASC, u.name ASC, u.id ASC LIMIT #{limit}

SELECT u.id, u.account, u.name, u.employee_no, u.phone, u.email, u.org_id, u.company_id, u.position, u.status, u.remark, u.last_login_at, u.created_at, u.updated_at, u.deleted_at FROM sys_user u WHERE 1 = 1 AND /* @dataScope(table=sys_user, alias=u) */ AND u.deleted_at IS NULL
AND u.status = #{status}
AND u.company_id = #{companyId}
AND u.org_id IN (SELECT so.id FROM sys_org so WHERE so.path LIKE #{orgPathPrefix})
AND u.org_id = #{orgId}
AND (u.name LIKE CONCAT('%', #{keyword}, '%') OR u.account LIKE CONCAT('%', #{keyword}, '%') OR u.employee_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.org_id ASC, u.id ASC
